const { sortByTransactionId } = require("../utils/sort");

const STATUS_ORDER = {
  pending: 0,
  approved: 1,
  rejected: 2,
  reversed: 3,
};

function reconcileTransactions(parsed) {
  const byId = new Map();
  for (const row of parsed.ledger) {
    byId.set(row.transaction_id, { ...row });
  }

  // Apply meeting amendments (owner changes) first.
  for (const amend of parsed.meetings) {
    const target = byId.get(amend.transaction_id);
    if (!target) continue;
    if (amend.signed) {
      target.owner = amend.owner;
    }
  }

  // Apply compliance mail status changes.
  for (const mail of parsed.emails) {
    const target = byId.get(mail.transaction_id);
    if (!target) continue;
    if (mail.status && STATUS_ORDER[mail.status] >= STATUS_ORDER[target.status]) {
      target.status = mail.status;
    }
  }

  // Policy exception transactions approved_by compliance.
  const policyWaiverTxns = new Set(
    (parsed.policyExceptions || [])
      .filter((e) => String(e.approved_by || "").toLowerCase() === "compliance")
      .map((e) => e.transaction_id),
  );

  // Apply correction notices in notice_id order; build reconciliation report.
  const report = [];
  const statusCorrectionApplied = new Set();
  const sortedNotices = [...parsed.corrections].sort((a, b) => {
    if (a.notice_id === b.notice_id) return 0;
    return a.notice_id < b.notice_id ? -1 : 1;
  });

  for (const notice of sortedNotices) {
    const target = byId.get(notice.transaction_id);
    if (!target) continue;

    let previousValue = "";
    if (notice.field === "owner") {
      previousValue = String(target.owner ?? "");
      target.owner = notice.value;
    } else if (notice.field === "status") {
      previousValue = String(target.status ?? "");
      target.status = notice.value;
      statusCorrectionApplied.add(notice.transaction_id);
    } else if (notice.field === "date") {
      previousValue = String(target.date ?? "");
      target.date = notice.value;
    } else {
      continue;
    }

    report.push({
      notice_id: notice.notice_id,
      transaction_id: notice.transaction_id,
      field: notice.field,
      previous_value: previousValue,
      new_value: notice.value,
      effective: notice.effective,
    });
  }

  report.sort((a, b) => {
    if (a.notice_id === b.notice_id) return 0;
