      codes.sort();
      const exception_reason = codes.length ? codes.join(";") : null;

      return {
        transaction_id: row.transaction_id,
        owner: row.owner,
        status,
        effective_date: row.date,
        amount_usd: Number(amount.toFixed(2)),
        exception_reason,
      };
    }),
